// steer's OpenCode plugin. OpenCode calls plugins in-process rather than
// spawning anything, so this file runs the steer binary and turns its answer
// into a thrown error or an edited command.
//
// Generated by `steer init --agent opencode`, which refuses to overwrite an
// existing file. An edit here survives, and stops matching the binary it talks
// to: after upgrading steer, run that command again with `--force`.
//
// Nothing is imported on purpose: no package has to resolve, so the file works
// the moment it lands.

const TIMEOUT_MS = 5000;

// The one place steer's fail-open guarantee leaves Rust: every failure returns
// null, and null lets the tool call through untouched.
async function ask(payload) {
  try {
    const child = Bun.spawn(
      ["steer", "hook", "--event", "PreToolUse", "--agent", "opencode"],
      {
        stdin: new TextEncoder().encode(JSON.stringify(payload)),
        stdout: "pipe",
        stderr: "ignore",
        timeout: TIMEOUT_MS,
      },
    );
    const text = await new Response(child.stdout).text();
    await child.exited;
    const answer = JSON.parse(text);
    return typeof answer.outcome === "string" ? answer : null;
  } catch {
    return null;
  }
}

// OpenCode calls every export in this file and rejects one that is not a
// function, so anything added beside this has to be a plugin too.
export const SteerPlugin = async ({ directory }) => ({
  "tool.execute.before": async (input, output) => {
    const answer = await ask({
      tool: input.tool,
      args: output.args,
      cwd: directory,
    });
    if (!answer) return;
    if (answer.outcome === "deny") {
      throw new Error(answer.message);
    }
    if (answer.outcome === "rewrite") {
      // OpenCode hands this same object to the tool; reassigning `output.args`
      // would drop the edit.
      output.args.command = answer.updated_command;
    } else if (answer.message) {
      // A message on an allowed call is steer reporting a broken config.
      console.error(answer.message);
    }
  },
});
